<button id="cartButton" class="fixed inset-x-4 bottom-4 z-30 mx-auto hidden max-w-xl items-center justify-between rounded-xl bg-[#16A34A] px-5 py-4 text-white shadow-xl"><span><b id="cartCount">0 item</b><small class="block text-emerald-100">Lihat keranjang</small></span><b id="cartTotal">Rp 0</b></button>

<dialog id="productDialog" class="w-[calc(100%-2rem)] max-w-lg rounded-2xl p-0 backdrop:bg-black/50"><form method="dialog" class="border-b p-4 text-right"><button class="rounded-lg px-3 py-1 text-sm font-bold">Tutup</button></form><div class="p-5"><img id="pdImage" class="mb-4 h-48 w-full rounded-xl object-cover"><h2 id="pdName" class="text-xl font-black"></h2><p id="pdDesc" class="mt-1 text-sm text-[#64748B]"></p><div id="variantBox" class="mt-4"></div><div id="addonBox" class="mt-4"></div><label class="mt-4 block text-sm font-semibold">Catatan<input id="pdNote" class="mt-1 h-11 w-full rounded-lg border-[#D0D5DD]" placeholder="Contoh: tanpa es"></label><div class="mt-5 flex items-center gap-3"><input id="pdQty" type="number" value="1" min="1" class="h-12 w-20 rounded-lg border-[#D0D5DD] text-center"><button id="addProduct" type="button" class="h-12 flex-1 rounded-lg bg-[#16A34A] px-4 font-bold text-white">Tambah · <span id="pdPrice"></span></button></div></div></dialog>

<dialog id="cartDialog" class="h-[90vh] w-full max-w-xl rounded-t-3xl p-0 backdrop:bg-black/50 sm:rounded-2xl"><div class="flex h-full flex-col"><div class="flex items-center justify-between border-b p-5"><div><h2 class="text-xl font-black">Keranjang</h2><p class="text-sm text-[#64748B]">Meja {{ $table->name }}</p></div><button onclick="cartDialog.close()" class="font-bold">Tutup</button></div><div id="cartLines" class="flex-1 space-y-3 overflow-y-auto p-5"></div><div class="border-t bg-white p-5"><label class="block text-sm font-semibold">Nama pemesan<input id="guestName" maxlength="80" class="mt-1 h-11 w-full rounded-lg border-[#D0D5DD]" placeholder="Opsional"></label><p class="mb-2 mt-4 text-sm font-bold">Metode pembayaran</p><label class="mb-2 flex cursor-pointer items-center gap-3 rounded-xl border p-3"><input type="radio" name="payment" value="cashier" checked><span><b class="block">Bayar di kasir</b><small class="text-[#64748B]">Tunai, QRIS, debit atau metode lain di kasir</small></span></label><label class="flex cursor-pointer items-center gap-3 rounded-xl border p-3"><input type="radio" name="payment" value="qris"><span><b class="block">Bayar QRIS sekarang</b><small class="text-[#64748B]">Diproses melalui BayarPro</small></span></label><div class="mt-4 flex justify-between text-lg font-black"><span>Total</span><span id="checkoutTotal"></span></div><button id="checkoutButton" class="mt-4 h-12 w-full rounded-lg bg-[#16A34A] font-bold text-white">Buat pesanan</button><p id="checkoutError" class="mt-2 hidden text-sm text-red-600"></p></div></div></dialog>

<script>
const rupiah=n=>'Rp '+Math.round(n).toLocaleString('id-ID'); let selected=null, cart=[];
const productDialog=document.getElementById('productDialog'), cartDialog=document.getElementById('cartDialog');
document.querySelectorAll('.product-card').forEach(b=>b.onclick=()=>{selected=JSON.parse(b.dataset.product); pdImage.src=selected.image;pdName.textContent=selected.name;pdDesc.textContent=selected.description||'';pdQty.value=1;pdNote.value='';variantBox.innerHTML=selected.variants.length?'<p class="mb-2 text-sm font-bold">Pilihan</p>'+selected.variants.map((v,i)=>`<label class="mb-2 flex gap-2 rounded-lg border p-3"><input type="radio" name="variant" value="${v.id}" data-adj="${v.adjustment}" ${i===0?'checked':''}>${v.name} ${v.adjustment?`(+${rupiah(v.adjustment)})`:''}</label>`).join(''):'';addonBox.innerHTML=selected.addons.length?'<p class="mb-2 text-sm font-bold">Tambahan</p>'+selected.addons.map(a=>`<label class="mb-2 flex gap-2 rounded-lg border p-3"><input type="checkbox" name="addon" value="${a.id}" data-price="${a.price}">${a.name} (+${rupiah(a.price)})</label>`).join(''):'';updatePd();productDialog.showModal()});
function updatePd(){let v=productDialog.querySelector('[name=variant]:checked'), addons=[...productDialog.querySelectorAll('[name=addon]:checked')];let price=selected.price+(v?+v.dataset.adj:0)+addons.reduce((s,a)=>s+(+a.dataset.price),0);pdPrice.textContent=rupiah(price*(+pdQty.value||1))} productDialog.addEventListener('change',updatePd);pdQty.oninput=updatePd;
addProduct.onclick=()=>{let v=productDialog.querySelector('[name=variant]:checked'),addons=[...productDialog.querySelectorAll('[name=addon]:checked')];cart.push({product_id:selected.id,name:selected.name,price:selected.price,qty:+pdQty.value,variant_id:v?+v.value:null,variant_name:v?v.parentElement.textContent.trim():'',variant_adjustment:v?+v.dataset.adj:0,addons:addons.map(a=>({addon_id:+a.value,name:a.parentElement.textContent.trim(),price:+a.dataset.price})),notes:pdNote.value});productDialog.close();renderCart()};
function lineTotal(i){return (i.price+i.variant_adjustment+i.addons.reduce((s,a)=>s+a.price,0))*i.qty} function total(){return cart.reduce((s,i)=>s+lineTotal(i),0)}
function renderCart(){cartButton.classList.toggle('hidden',!cart.length);cartButton.classList.toggle('flex',!!cart.length);cartCount.textContent=cart.reduce((s,i)=>s+i.qty,0)+' item';cartTotal.textContent=rupiah(total());checkoutTotal.textContent=rupiah(total());cartLines.innerHTML=cart.map((i,x)=>`<div class="rounded-xl border p-4"><div class="flex justify-between gap-3"><div><b>${i.qty}× ${i.name}</b><p class="text-xs text-slate-500">${i.variant_name}${i.addons.length?' · '+i.addons.map(a=>a.name).join(', '):''}</p></div><b>${rupiah(lineTotal(i))}</b></div><button onclick="cart.splice(${x},1);renderCart()" class="mt-2 text-xs font-bold text-red-600">Hapus</button></div>`).join('')||'<p>Keranjang kosong.</p>'} cartButton.onclick=()=>{renderCart();cartDialog.showModal()};
checkoutButton.onclick=async e=>{e.preventDefault();checkoutButton.disabled=true;checkoutButton.textContent='Memproses...';checkoutError.classList.add('hidden');try{let res=await fetch(@json(route('self-order.place',$table->public_token)),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify({session_token:@json($session->guest_token),guest_name:guestName.value,payment_choice:document.querySelector('[name=payment]:checked').value,items:cart.map(i=>({product_id:i.product_id,qty:i.qty,variant_id:i.variant_id,addons:i.addons.map(a=>({addon_id:a.addon_id})),notes:i.notes}))})});let data=await res.json();if(!res.ok)throw new Error(data.message||'Pesanan gagal dibuat.');location.href=data.status_url}catch(err){checkoutError.textContent=err.message;checkoutError.classList.remove('hidden');checkoutButton.disabled=false;checkoutButton.textContent='Buat pesanan'}};
</script></body></html>
